// FICHIER GÉNÉRÉ par scripts/preparer-edge-functions.mjs — modifier gabarits/, pas ce fichier.
// Clés : chemin relatif dans gabarits/ (ex. « 02-AVT.html », « fragments/styles.css »).
export const GABARITS: Record<string, string> = {
  "00-AVT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Recueil des besoins — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Recueil des besoins — pré-formation</h1>\n<p class=\"sous-titre\">Attentes, niveau de départ et objectifs spécifiques — indicateurs Qualiopi n° 1 et 4</p>\n<div class=\"fiche\">\n  <div>Stagiaire</div><div class=\"v\">{{stagiaire_1_nom}}</div>\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Durée</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<p>Recueil effectué le <span class=\"v\">{{recueil_date}}</span> par le formateur {{formateur_prenom}} {{formateur_nom}}.</p>\n<!-- zone:reponses_recueil -->\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le formateur</div>\n    <div class=\"nom\">{{formateur_prenom}} {{formateur_nom}}</div>\n    <!-- zone:signature_formateur -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "01-AVT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Test de positionnement — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Test de positionnement</h1>\n<p class=\"sous-titre\">Évaluation diagnostique initiale des prérequis — indicateur Qualiopi n° 8</p>\n<div class=\"fiche\">\n  <div>Stagiaire</div><div class=\"v\">{{stagiaire_1_nom}}</div>\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Durée</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<!-- si:formation_prerequis --><div class=\"encadre\"><span class=\"v\">Prérequis de la formation.</span> {{formation_prerequis}}</div><!-- /si:formation_prerequis -->\n<p>Test réalisé le <span class=\"v\">{{positionnement_date}}</span>.</p>\n<!-- zone:questions_positionnement -->\n<!-- si:positionnement_ajustement --><h2>Ajustement du programme</h2><p>{{positionnement_ajustement}}</p><!-- /si:positionnement_ajustement -->\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le formateur</div>\n    <div class=\"nom\">{{formateur_prenom}} {{formateur_nom}}</div>\n    <!-- zone:signature_formateur -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "02-AVT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Convention de formation professionnelle — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Convention de formation professionnelle</h1>\n<p class=\"sous-titre\">Convention n° {{dossier_reference}} — conclue en application de l'article L.6313-1 du Code du travail : action d'adaptation et de développement des compétences.</p>\n\n<p>Entre les soussignés :</p>\n<div class=\"parties\">\n  <div class=\"partie\">\n    <div class=\"role\">L'organisme prestataire</div>\n    <p><span class=\"v\">{{of_nom}}</span><br>{{of_adresse}}</p>\n    <p>SIRET : {{of_siret}}<br>\n    Enregistré sous le n° de déclaration d'activité {{of_nda_numero}} auprès de la DREETS {{of_dreets_region}}</p>\n    <p>Représenté par : <span class=\"v\">{{of_representant_civilite}} {{of_representant_prenom}} {{of_representant_nom}}</span></p>\n    <p class=\"mention\">Ci-après dénommé « l'Organisme prestataire d'actions concourant au développement des compétences ».</p>\n  </div>\n  <div class=\"partie\">\n    <div class=\"role\">L'entreprise commanditaire</div>\n    <p><span class=\"v\">{{entreprise_nom}}</span><!-- si:entreprise_nom_commercial --><br>Nom commercial : {{entreprise_nom_commercial}}<!-- /si:entreprise_nom_commercial --><br>{{entreprise_adresse}}</p>\n    <p>SIRET : {{entreprise_siret}}</p>\n    <p>Représentée par : <span class=\"v\">{{entreprise_representant_civilite}} {{entreprise_representant_prenom}} {{entreprise_representant_nom}}</span></p>\n    <p class=\"mention\">Ci-après dénommée « le Commanditaire » de l'action définie à l'article 1.</p>\n  </div>\n</div>\n\n<h2>Article 1 — Détail de l'action de formation (article L.6353-1 du Code du travail)</h2>\n<div class=\"fiche\">\n  <div>1.1 Intitulé</div><div class=\"v\">{{formation_titre}}</div>\n  <div>1.2 Objectifs</div><div>{{formation_objectifs}}<br><span class=\"mention\">Le programme détaillé de l'action de formation figure en annexe à la présente convention.</span></div>\n  <div>1.3 Niveau</div><div>{{formation_niveau}}</div>\n  <div>1.4 Dates</div><div>Du <span class=\"v\">{{formation_date_debut}}</span> au <span class=\"v\">{{formation_date_fin}}</span> — voir le planning en annexe.</div>\n  <div>1.5 Durée</div><div><span class=\"v\">{{formation_duree_heures_total}} heures</span> sur {{formation_duree_jours}} jour(s)<!-- si:formation_duree_heures_presentiel -->, dont {{formation_duree_heures_presentiel}} heures en présentiel<!-- /si:formation_duree_heures_presentiel --><!-- si:formation_duree_heures_distanciel -->, dont {{formation_duree_heures_distanciel}} heures à distance<!-- /si:formation_duree_heures_distanciel -->.</div>\n  <div>1.7 Lieu</div><div>{{formation_lieu_nom}}<br>{{formation_lieu_adresse}}<!-- si:formation_lieu_siret --><br>SIRET du lieu de formation : {{formation_lieu_siret}}<!-- /si:formation_lieu_siret --></div>\n  <div>1.8 Modalité</div><div><span class=\"v\">{{formation_modalite}}</span>. Les formations sont individuelles ou en groupe (2 à 12 stagiaires), animées par un formateur.</div>\n  <div>1.9 Prérequis</div><div>{{formation_prerequis}}</div>\n</div>\n\n<h3>1.6 Effectif de l'action de formation</h3>\n<table>\n  <thead><tr><th style=\"width:10mm\">N°</th><th>Prénom et nom du stagiaire</th><th>Poste occupé</th></tr></thead>\n  <tbody>\n  <!-- repeter:stagiaire --><tr><td>{{rang_stagiaire}}</td><td class=\"v\">{{stagiaire_N_nom}}</td><td>{{stagiaire_N_poste}}</td></tr>\n  <!-- /repeter:stagiaire -->\n  </tbody>\n</table>\n\n<h3>1.10 Moyens pédagogiques et techniques mis en œuvre</h3>\n<p>Voir le programme de formation en annexe, qui détaille les moyens mis en œuvre pour réaliser techniquement l'action, suivre son exécution et apprécier ses résultats.</p>\n<p><span class=\"v\">Encadrement.</span> La formation est assurée par {{of_nom}}, qui met à disposition un formateur expérimenté dans son domaine, disponible selon les modalités et plages horaires préalablement définies.</p>\n<p><span class=\"v\">Accompagnement pédagogique.</span> Un conseiller référent (suivi personnalisé, prises de contact régulières, forte disponibilité) est en charge de l'apprenant dès l'entrée en formation et tout au long du parcours pédagogique.</p>\n<h3>1.11 Modalités de sanction</h3>\n<p>Délivrance d'une attestation de formation et/ou d'une certification selon les cas.</p>\n<h3>1.12 Moyens de contrôle de l'assiduité</h3>\n<p>Attestation d'assiduité, feuille d'émargement pour les formations en présentiel, relevé de fréquentation pour les formations synchrones, relevé de connexion pour les formations asynchrones.</p>\n<h3>1.13 Modalités d'évaluation</h3>\n<ul>\n  <li>Travaux et évaluation intermédiaire</li>\n  <li>Tests d'évaluation et de progression, exercices, échanges avec le formateur</li>\n  <li>Travaux et évaluation finale</li>\n  <li>Passage d'une certification si elle est incluse dans le programme</li>\n</ul>\n\n<h2>Article 2 — Engagement de participation</h2>\n<p>Le Commanditaire s'engage à assurer la présence du ou des participants aux dates, lieux et heures prévus à l'article 1.</p>\n\n<h2>Article 3 — Dispositions financières</h2>\n<p>En contrepartie de cette action de formation, le Commanditaire (ou le financeur dans le cadre d'une subrogation de paiement) s'acquittera des coûts suivants, qui couvrent l'intégralité des frais engagés par l'organisme de formation pour cette session :</p>\n<table>\n  <thead><tr><th>Désignation</th><th class=\"num\">Coût unitaire HT</th><th class=\"num\">Stagiaires</th><th class=\"num\">Total HT</th></tr></thead>\n  <tbody>\n    <tr><td>Coûts pédagogiques — {{formation_titre}}</td><td class=\"num\">{{formation_prix_unitaire_ht}}</td><td class=\"num\">{{formation_nb_stagiaires}}</td><td class=\"num v\">{{formation_prix_total_ht}}</td></tr>\n    <!-- si:formation_prix_presentiel_ht --><tr><td colspan=\"3\">dont heures en présentiel</td><td class=\"num\">{{formation_prix_presentiel_ht}}</td></tr><!-- /si:formation_prix_presentiel_ht -->\n  </tbody>\n</table>\n<div class=\"encadre\">Total net de taxe — TVA non applicable (article 261.4.4° du CGI) : <span class=\"v\">{{formation_prix_total_ht}}</span></div>\n<p><span class=\"v\">Modalités de règlement.</span> Le règlement se fait par chèque ou virement bancaire à réception de facture.</p>\n<!-- si:formation_opco --><p>L'opérateur de compétences est : <span class=\"v\">{{formation_opco}}</span>.</p><!-- /si:formation_opco -->\n<!-- si:formation_clause_subrogation --><p>{{formation_clause_subrogation}}</p><!-- /si:formation_clause_subrogation -->\n<p>Seuls les participants déclarés et les heures attestées par l'émargement sont facturables à l'OPCO ou au FAF ; les montants qui lui sont facturés sont calculés au prorata des heures de formation réalisées et attestées, le reste étant à la charge de l'entreprise.</p>\n<p>En cas de subrogation de paiement par un OPCO, le Commanditaire s'engage à payer les montants non pris en charge par celui-ci. L'absence partielle ou totale d'un ou plusieurs stagiaires ne donne lieu à aucune réduction du prix final de la prestation. En cas de refus de subrogation par l'OPCO, le FAF ou un autre financeur, le règlement peut s'effectuer en 4 ou 6 mensualités.</p>\n\n<h2>Article 4 — Délai de rétractation (article L.6353-5)</h2>\n<p>Le Commanditaire est informé qu'il dispose d'un délai de rétractation de 15 jours à compter de la date de la conclusion du présent contrat. Le cas échéant, le stagiaire informe l'organisme de formation par lettre recommandée avec accusé de réception. Aucune somme ne peut être exigée du Commanditaire qui a exercé son droit de rétractation dans les délais prévus.</p>\n\n<h2>Article 5 — Dédommagement, réparation ou dédit</h2>\n<p>En cas de renoncement par le Commanditaire avant le début du programme de formation :</p>\n<ul>\n  <li>plus d'un mois avant le début de la formation : néant ;</li>\n  <li>entre un mois et deux semaines avant le début de la formation : 30 % du coût de la formation est dû ;</li>\n  <li>moins de deux semaines avant le début de la formation : 50 % du coût de la formation est dû.</li>\n</ul>\n<p>Ce coût ne peut faire l'objet d'une demande de remboursement ou de prise en charge par l'OPCO.</p>\n\n<h2>Article 6 — Conditions d'annulation et de report</h2>\n<p>Toute annulation ou demande de report par le Commanditaire doit être communiquée à l'organisme de formation par lettre recommandée avec accusé de réception au minimum 15 jours avant le début de la formation. Toute demande reçue hors délai n'est pas recevable et entraîne l'obligation, pour le Commanditaire, de s'acquitter immédiatement de la somme mentionnée à l'article 5.</p>\n<p>{{of_nom}} peut annuler ou reporter la formation sans frais en informant le Commanditaire au moins 7 jours ouvrés avant le début de la prestation. En cas d'indisponibilité du formateur ou de toute autre circonstance extérieure indépendante de {{of_nom}}, la formation peut être annulée ou reportée sans préavis ; {{of_nom}} s'engage alors à proposer une nouvelle date aussi proche que possible de la date initialement prévue.</p>\n\n<h2>Article 7 — Non-réalisation de la prestation de formation</h2>\n<p>En application de l'article L.6354-1 du Code du travail, il est convenu entre les signataires que, faute de réalisation totale ou partielle de la prestation de formation, l'organisme prestataire rembourse au cocontractant les sommes indûment perçues de ce fait.</p>\n\n<h2>Article 8 — Prise d'effet</h2>\n<p>La présente convention prend effet à compter de sa signature par l'entreprise et pour la durée de la formation.</p>\n\n<h2>Article 9 — Nullité</h2>\n<p>Si une ou plusieurs dispositions de la présente convention sont déclarées nulles en application d'une loi, d'un règlement ou à la suite d'une décision définitive d'une juridiction compétente, elles sont considérées comme détachables. Les autres dispositions restent valides et en vigueur, à moins que l'une des parties ne démontre que la disposition annulée revêt un caractère essentiel et déterminant sans lequel elle n'aurait pas contracté.</p>\n\n<h2>Article 10 — Litiges</h2>\n<p>Si une contestation ou un différend ne peut être réglé à l'amiable, le {{of_tribunal_competent}} sera seul compétent pour régler le litige.</p>\n\n<h2>Article 11 — Protection des données personnelles</h2>\n<p>Le traitement des données à caractère personnel mis en œuvre par la Société s'inscrit dans le strict respect de la loi du 6 juin 2004 sur la protection de l'économie numérique, de la loi du 6 janvier 1978 relative à l'informatique, aux fichiers et aux libertés telle qu'elle a été modifiée par la loi du 20 juin 2018 relative à la protection des données personnelles, ainsi que du Règlement européen général sur la protection des données en date du 27 avril 2016, entré en vigueur le 25 mai 2018.</p>\n<p>Il s'inscrit également dans l'exécution de la relation contractuelle entre la Société et le Client telle qu'elle résulte du présent contrat, de sorte que ce dernier constitue la base juridique du traitement et de la collecte des données à caractère personnel du Client.</p>\n<p>Dès lors, la Société met en œuvre des traitements de données à caractère personnel qui ont pour base juridique :</p>\n<ul>\n  <li>l'intérêt légitime poursuivi par la Société lorsqu'elle poursuit les finalités suivantes : prospection et animation ; gestion de la relation avec ses clients et prospects ; organisation, inscription et invitation aux événements de la Société ;</li>\n  <li>l'exécution de mesures précontractuelles ou du contrat lorsqu'elle met en œuvre un traitement ayant pour finalités la production, la gestion, le suivi des dossiers de ses clients ; le recouvrement ;</li>\n  <li>le respect d'obligations légales et réglementaires lorsqu'elle met en œuvre un traitement ayant pour finalités la gestion de la facturation et de la comptabilité.</li>\n</ul>\n<p>La Société ne conserve les données que pour la durée nécessaire aux opérations pour lesquelles elles ont été collectées ainsi que dans le respect de la réglementation en vigueur. À cet égard, les données des clients sont conservées pendant la durée des relations contractuelles augmentée de 3 ans à des fins d'animation et de prospection, sans préjudice des obligations de conservation ou des délais de prescription. En matière de comptabilité, elles sont conservées 10 ans à compter de la clôture de l'exercice comptable.</p>\n<p>Le Client est informé qu'il dispose des droits d'accès, de rectification, d'effacement, de limitation, du droit à la portabilité de ses données à caractère personnel ainsi que du droit d'opposition au traitement desdites données, dans les conditions et limites d'application des articles 15 à 21 du Règlement général relatif à la protection des données personnelles.</p>\n<p>Il peut exercer ces droits en contactant {{of_representant_civilite}} {{of_representant_prenom}} {{of_representant_nom}} par courriel à {{of_email_pedagogie}}, en accompagnant sa demande d'une copie de sa pièce d'identité. Le Client dispose également du droit d'introduire une réclamation auprès de la CNIL.</p>\n\n<p style=\"margin-top:7mm\">Fait en 3 exemplaires à <span class=\"v\">{{signature_lieu}}</span>, le <span class=\"v\">{{signature_date}}</span>.</p>\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Pour l'organisme de formation</div>\n    <div class=\"nom\">{{of_representant_prenom}} {{of_representant_nom}}</div>\n    <!-- zone:signature_of -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Pour l'entreprise commanditaire — {{entreprise_nom}}</div>\n    <div class=\"nom\">{{entreprise_representant_prenom}} {{entreprise_representant_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n</div>\n<p class=\"mention\">Pas de tampon en cas de signature électronique.</p>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "03-AVT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Planning de formation — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Planning de formation</h1>\n<p class=\"sous-titre\">Annexe à la convention n° {{dossier_reference}}</p>\n<div class=\"fiche\">\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Stagiaire(s)</div><div>{{formation_liste_stagiaires}}</div>\n  <div>Période</div><div>Du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Durée totale</div><div>{{formation_duree_heures_total}} heures sur {{formation_duree_jours}} jour(s)</div>\n  <div>Lieu de formation</div><div>{{formation_lieu_adresse}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<h2>Détail du planning</h2>\n<table>\n  <thead><tr><th style=\"width:22mm\">Séance</th><th>Date</th><th>Heure de début</th><th>Heure de fin</th></tr></thead>\n  <tbody>\n  <!-- repeter:session --><tr><td>Séance {{rang_session}}</td><td class=\"v\">{{session_N_date}}</td><td>{{session_N_heure_debut}}</td><td>{{session_N_heure_fin}}</td></tr>\n  <!-- /repeter:session -->\n  </tbody>\n</table>\n<p class=\"mention\">Planning transmis en annexe de la convention de formation. Toute modification fait l'objet d'un nouveau planning communiqué aux parties.</p>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "04-AVT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Contrat de sous-traitance de formation — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Contrat de sous-traitance de formation</h1>\n<p class=\"sous-titre\">Ordre de mission n° {{dossier_reference}}</p>\n\n<p>Entre les soussignés :</p>\n<div class=\"parties\">\n  <div class=\"partie\">\n    <div class=\"role\">Le donneur d'ordre</div>\n    <p><span class=\"v\">{{of_nom}}</span><br>{{of_adresse}}</p>\n    <p>SIRET : {{of_siret}}<br>Organisme de formation enregistré sous le numéro {{of_nda_numero}} auprès de la DREETS {{of_dreets_region}}</p>\n    <p>Représenté par : <span class=\"v\">{{of_representant_prenom}} {{of_representant_nom}}</span></p>\n  </div>\n  <div class=\"partie\">\n    <div class=\"role\">Le sous-traitant</div>\n    <p><span class=\"v\">{{formateur_entreprise_nom}}</span><br>{{formateur_entreprise_adresse}}</p>\n    <p>SIRET : {{formateur_entreprise_siret}}<br>Organisme de formation enregistré sous le numéro {{formateur_nda_numero}} auprès de la DREETS {{formateur_dreets_region}}</p>\n    <p>Représenté par : <span class=\"v\">{{formateur_prenom}} {{formateur_nom}}</span></p>\n  </div>\n</div>\n<p>Il a été convenu ce qui suit :</p>\n\n<h2>Article 1 — Nature du contrat</h2>\n<p>Le présent contrat est conclu dans le cadre d'une prestation de formation ponctuelle réalisée par le sous-traitant au bénéfice du donneur d'ordre.</p>\n\n<h2>Article 2 — Objet du contrat</h2>\n<p>La formation, objet du contrat, est la suivante :</p>\n<div class=\"fiche\">\n  <div>a) Intitulé</div><div class=\"v\">{{formation_titre}}</div>\n  <div>b) Dates</div><div>Du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>c) Durée</div><div>{{formation_duree_heures_total}} heures<!-- si:formation_duree_heures_presentiel -->, dont {{formation_duree_heures_presentiel}} heures en présentiel<!-- /si:formation_duree_heures_presentiel --></div>\n  <div>d) Objectifs de la mission</div><div>{{formation_objectifs}}</div>\n  <div>e) Programme et méthodes</div><div>Méthodes d'animation participatives : interactivité, exemples et cas pratiques. Procédés pédagogiques adaptés au niveau du ou des participants. Travaux pratiques adaptés à l'activité du client.</div>\n  <div>f) Lieu</div><div>{{formation_lieu_adresse}}</div>\n  <div>g) Société cliente</div><div>{{entreprise_nom}}</div>\n  <div>h) Responsable</div><div>{{entreprise_representant_prenom}} {{entreprise_representant_nom}}<!-- si:entreprise_representant_telephone --> — {{entreprise_representant_telephone}}<!-- /si:entreprise_representant_telephone --></div>\n</div>\n<h3>i) Effectif de l'action de formation</h3>\n<table>\n  <thead><tr><th style=\"width:10mm\">N°</th><th>Stagiaire</th><th>Poste occupé</th></tr></thead>\n  <tbody>\n  <!-- repeter:stagiaire --><tr><td>{{rang_stagiaire}}</td><td>{{stagiaire_N_nom}}</td><td>{{stagiaire_N_poste}}</td></tr>\n  <!-- /repeter:stagiaire -->\n  </tbody>\n</table>\n\n<h2>Article 3 — Durée du contrat</h2>\n<p>Le présent contrat est strictement limité à la prestation de formation visée à l'article 2. Il cesse de plein droit à son terme.</p>\n\n<h2>Article 4 — Modalités financières</h2>\n<p>Le sous-traitant percevra une rémunération de <span class=\"v\">{{formateur_cout_horaire}}</span> par heure, net de taxe — TVA non applicable (article 261.4.4° du CGI), soit un total de <span class=\"v\">{{formateur_montant_total}}</span>.</p>\n<p>Le règlement interviendra sous 10 jours après le règlement du client ou du financeur.</p>\n\n<h2>Article 5 — Obligations du sous-traitant</h2>\n<p>Le sous-traitant s'engage à :</p>\n<ul>\n  <li>communiquer au donneur d'ordre une copie de son extrait K-bis ou de son immatriculation avant le début de la formation ;</li>\n  <li>animer la formation dans le respect des objectifs fixés par le donneur d'ordre ;</li>\n  <li>animer personnellement la formation, sauf situation exceptionnelle et uniquement après accord écrit du donneur d'ordre ;</li>\n  <li>assurer l'évaluation des stagiaires à l'issue de l'action de formation, afin de permettre au donneur d'ordre d'établir les attestations de fin de formation prévues à l'article L.6353-1 du Code du travail ;</li>\n  <li>participer aux réunions de préparation, aux jurys d'examen et aux remises de diplôme.</li>\n</ul>\n\n<h2>Article 6 — Obligations du donneur d'ordre</h2>\n<p>Le donneur d'ordre s'engage à :</p>\n<ul>\n  <li>confier au sous-traitant la formation prévue à l'article 2 ;</li>\n  <li>prendre en charge la gestion administrative et logistique de la formation ;</li>\n  <li>transmettre au sous-traitant les feuilles de présence à faire signer par le stagiaire ;</li>\n  <li>transmettre au sous-traitant une copie des questionnaires de satisfaction à faire remplir par le stagiaire à l'issue de la formation ;</li>\n  <li>prévenir le sous-traitant au moins 8 jours à l'avance en cas d'annulation ou de report de la formation.</li>\n</ul>\n\n<h2>Article 7 — Dispositions diverses</h2>\n<p>Le présent contrat ne crée entre les parties aucun lien de subordination, le sous-traitant demeurant libre et responsable du contenu de la formation.</p>\n<p>Le sous-traitant dispose d'une propriété intellectuelle et/ou artistique sur le contenu de sa formation. Le donneur d'ordre s'engage à ne pas reproduire ni diffuser ce contenu sans l'accord du sous-traitant.</p>\n\n<h2>Article 8 — Différend</h2>\n<p>Tout contrat engage les parties à respecter chacune de ses clauses. Tout différend entre les parties relatif à l'existence, la validité, l'interprétation, l'exécution et la résiliation du présent contrat (ou de l'une quelconque de ses clauses), que les parties ne pourraient résoudre entre elles à l'amiable, sera soumis au {{of_tribunal_competent}}, seul compétent pour régler le litige.</p>\n\n<p style=\"margin-top:7mm\">Fait en double exemplaire à <span class=\"v\">{{signature_lieu}}</span>, le <span class=\"v\">{{signature_date}}</span>.</p>\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le donneur d'ordre</div>\n    <div class=\"nom\">{{of_representant_prenom}} {{of_representant_nom}}</div>\n    <!-- zone:signature_of -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le sous-traitant</div>\n    <div class=\"nom\">{{formateur_prenom}} {{formateur_nom}}</div>\n    <!-- zone:signature_formateur -->\n  </div>\n</div>\n<p class=\"mention\">Pas de tampon en cas de signature électronique.</p>\n\n<h1 class=\"saut\">Charte professionnelle du formateur</h1>\n<p class=\"sous-titre\">Annexe au contrat de sous-traitance n° {{dossier_reference}}</p>\n<p>En tant que professionnel de la formation, je m'engage à respecter la charte déontologique et de qualité professionnelle.</p>\n<h2>Titre I — Déontologie et éthique professionnelle</h2>\n<p>Je m'engage à exercer mon activité en appliquant les principes généraux de la déontologie et de l'éthique professionnelle : respect de la personne humaine ; indépendance de jugement et d'action ; honnêteté et neutralité ; respect de la confidentialité professionnelle.</p>\n<h2>Titre II — Relations avec les clients</h2>\n<ul>\n  <li>Donner des renseignements exacts sur ma formation, mes compétences professionnelles et mes spécialisations.</li>\n  <li>Tenir compte du travail de préparation et des processus administratifs avant le commencement de tous travaux pédagogiques.</li>\n  <li>Respecter les engagements pris dans leur intégralité.</li>\n  <li>Exercer mon action dans l'intérêt commun du client et des bénéficiaires des actions de formation, en mettant en œuvre les moyens nécessaires pour atteindre les objectifs contractualisés.</li>\n  <li>Être neutre par rapport aux jeux d'influence chez le client et n'exprimer aucun jugement ou critique sur le client auprès des participants. Respecter la confidentialité des informations concernant le client et la culture de l'organisation cliente.</li>\n</ul>\n<h2>Titre III — Relations avec les participants des actions de formation</h2>\n<ul>\n  <li>Respecter la personnalité de chacun et m'interdire toute forme de discrimination.</li>\n  <li>Garantir aux bénéficiaires des actions la confidentialité absolue à propos de leurs paroles ou comportements, sauf s'ils présentent des risques pour l'action.</li>\n  <li>Entretenir avec les bénéficiaires des actions des relations empreintes de correction, de droiture et de neutralité.</li>\n  <li>M'interdire tout abus d'autorité ou de pouvoir lié à ma position.</li>\n</ul>\n<h2>Titre IV — Relations avec la profession</h2>\n<ul>\n  <li>Contribuer par mon comportement et la qualité de mes actions à renforcer l'image de la profession.</li>\n  <li>Me doter des moyens nécessaires à mon professionnalisme et au développement de mes compétences.</li>\n  <li>Connaître et appliquer les règles en vigueur dans la profession.</li>\n  <li>Veiller à établir le juste rapport qualité-prix de ma prestation.</li>\n</ul>\n<h2>Titre V — Respect du cadre légal</h2>\n<ul>\n  <li>Connaître et appliquer les lois et règlements, en particulier le livre IX du Code du travail pour les actions de formation professionnelle continue, et me tenir au courant de leur évolution.</li>\n  <li>Être en règle par rapport à toute obligation légale et fiscale.</li>\n  <li>N'accepter aucune rémunération illicite et informer des cadeaux reçus.</li>\n  <li>Citer mes sources et respecter la propriété intellectuelle.</li>\n</ul>\n<h2>Titre VI — Rapport aux méthodes et aux savoirs</h2>\n<p>Le formateur se situe dans la pédagogie active et place l'apprenant dans une démarche permanente d'évaluation et d'auto-évaluation. Il s'assure de la cohérence pédagogique de chaque module de formation par rapport à l'ensemble de la formation, ainsi que des choix pédagogiques et des contenus de référence.</p>\n<h2>Titre VII — Accessibilité aux personnes en situation de handicap</h2>\n<p>Je m'engage à assurer l'accès à toute personne en situation de handicap et à m'adapter à sa situation particulière.</p>\n<div class=\"encadre\">Le formateur, <span class=\"v\">{{formateur_prenom}} {{formateur_nom}}</span>, s'engage à respecter cette charte — le {{signature_date}}.</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "05-AVT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Convocation à la formation — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Convocation</h1>\n<p class=\"sous-titre\">{{formation_titre}}</p>\n\n<p>Bonjour <span class=\"v\">{{stagiaire_1_nom}}</span>,</p>\n<p>Nous avons le plaisir de vous convoquer à votre première séance de formation :</p>\n<div class=\"fiche\">\n  <div>Formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Première séance</div><div>Le <span class=\"v\">{{session_1_date}}</span>, de <span class=\"v\">{{session_1_heure_debut}}</span> à <span class=\"v\">{{session_1_heure_fin}}</span></div>\n  <div>Période</div><div>Du {{formation_date_debut}} au {{formation_date_fin}} — {{formation_duree_heures_total}} heures</div>\n  <div>Modalité</div><div>{{formation_modalite}}</div>\n  <!-- si:formation_lieu_adresse --><div>Lieu</div><div>{{formation_lieu_nom}}<br>{{formation_lieu_adresse}}</div><!-- /si:formation_lieu_adresse -->\n</div>\n\n<!-- si:formation_lien_visio -->\n<div class=\"encadre\">\n  <p><span class=\"v\">Lien de connexion.</span> Il est identique pour l'ensemble de la formation, dont le calendrier figure ci-dessous.</p>\n  <p>{{formation_lien_visio}}</p>\n</div>\n<h2>Équipement nécessaire</h2>\n<ul>\n  <li>Un micro-ordinateur et une connexion internet</li>\n  <li>Un casque avec micro (recommandé), ou le micro intégré à votre ordinateur</li>\n  <li>Une webcam — obligatoire</li>\n</ul>\n<!-- /si:formation_lien_visio -->\n\n<h2>Calendrier des séances</h2>\n<table>\n  <thead><tr><th style=\"width:18mm\">Séance</th><th>Date</th><th>Début</th><th>Fin</th></tr></thead>\n  <tbody>\n  <!-- repeter:session --><tr><td>{{rang_session}}</td><td>{{session_N_date}}</td><td>{{session_N_heure_debut}}</td><td>{{session_N_heure_fin}}</td></tr>\n  <!-- /repeter:session -->\n  </tbody>\n</table>\n\n<h2>Votre formateur</h2>\n<p><span class=\"v\">{{formateur_prenom}} {{formateur_nom}}</span><br>{{formateur_email}}<!-- si:formateur_telephone --> — {{formateur_telephone}}<!-- /si:formateur_telephone --></p>\n<!-- si:formation_prerequis --><h2>Prérequis</h2><p>{{formation_prerequis}}</p><!-- /si:formation_prerequis -->\n<p>Le programme de la formation et nos engagements qualité sont à votre disposition dans votre espace personnel. Si vous êtes en situation de handicap, contactez-nous à {{of_email_pedagogie}} afin que nous adaptions les conditions de votre formation.</p>\n\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">L'organisme de formation</div>\n    <div class=\"nom\">{{of_nom}}</div>\n    <!-- zone:signature_of -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire ou le responsable de l'entreprise — bon pour accusé de réception</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "06-PDT.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Feuille d'émargement — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page paysage\">\n<!-- inclure:entete -->\n\n<h1>Feuille d'émargement</h1>\n<p class=\"sous-titre\">Preuve de réalisation de l'action de formation — indicateur Qualiopi n° 17</p>\n<div class=\"fiche\">\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Objectif pédagogique</div><div>{{formation_objectifs}}</div>\n  <div>Durée totale</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Lieu de formation</div><div>{{formation_lieu_nom}} — {{formation_lieu_adresse}}</div>\n  <div>Entreprise cliente</div><div>{{entreprise_nom}} (SIRET : {{entreprise_siret}})</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<!-- repeter:stagiaire -->\n<h2>Stagiaire : {{stagiaire_N_nom}}</h2>\n<table>\n  <thead><tr><th style=\"width:34mm\">Date</th><th style=\"width:26mm\">Heure de début</th><th style=\"width:26mm\">Heure de fin</th><th>Signature du stagiaire</th><th>Signature du formateur</th></tr></thead>\n  <tbody>\n  <!-- repeter:session --><tr><td class=\"v\">{{session_N_date}}</td><td>{{session_N_heure_debut}}</td><td>{{session_N_heure_fin}}</td><td class=\"case-emargement\"><!-- zone:emargement_stagiaire --></td><td class=\"case-emargement\"><!-- zone:emargement_formateur --></td></tr>\n  <!-- /repeter:session -->\n  </tbody>\n</table>\n<!-- /repeter:stagiaire -->\n<p class=\"mention\">Chaque signature électronique est horodatée et rattachée à la séance et au signataire concernés. Feuille clôturée le dernier jour de la formation.</p>\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Validation de la feuille par le stagiaire</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le formateur</div>\n    <div class=\"nom\">{{formateur_prenom}} {{formateur_nom}}</div>\n    <!-- zone:signature_formateur -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "07-FIN.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Évaluation des acquis — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Évaluation des acquis</h1>\n<p class=\"sous-titre\">Validation des compétences acquises en fin de formation — indicateur Qualiopi n° 11</p>\n<div class=\"fiche\">\n  <div>Stagiaire</div><div class=\"v\">{{stagiaire_1_nom}}</div>\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Durée</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<div class=\"fiche\">\n  <div>Date de l'évaluation</div><div class=\"v\">{{evaluation_acquis_date}}</div>\n  <div>Résultat</div><div><span class=\"v\">{{evaluation_acquis_score}}</span> — niveau d'atteinte des objectifs : <span class=\"v\">{{evaluation_acquis_niveau_atteinte}}</span></div>\n</div>\n<!-- zone:questions_acquis -->\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le formateur</div>\n    <div class=\"nom\">{{formateur_prenom}} {{formateur_nom}}</div>\n    <!-- zone:signature_formateur -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "08-FIN.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Évaluation à chaud — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Grille d'évaluation « à chaud » de l'action de formation</h1>\n<p class=\"sous-titre\">Conditions de formation, pédagogie et formateur — indicateur Qualiopi n° 30</p>\n<div class=\"fiche\">\n  <div>Stagiaire</div><div class=\"v\">{{stagiaire_1_nom}}</div>\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Durée</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<div class=\"fiche\"><div>Organisme de formation</div><div>{{of_nom}}</div><div>Entreprise</div><div>{{entreprise_nom}}</div></div>\n<p>Chaque critère est noté de 1 (insuffisant) à 5 (excellent).</p>\n<!-- zone:grille_satisfaction_chaud -->\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "09-FIN.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Attestation de réalisation — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Attestation de réalisation de formation</h1>\n<p class=\"sous-titre\">Durée réalisée et niveau d'atteinte des objectifs — indicateur Qualiopi n° 11</p>\n<p>Je soussigné(e) <span class=\"v\">{{of_representant_civilite}} {{of_representant_prenom}} {{of_representant_nom}}</span>, représentant légal de l'organisme de formation <span class=\"v\">{{of_nom}}</span>, atteste que :</p>\n<div class=\"encadre\" style=\"font-size:12pt\"><span class=\"v\">{{stagiaire_1_nom}}</span><!-- si:stagiaire_1_poste -->, {{stagiaire_1_poste}}<!-- /si:stagiaire_1_poste -->, salarié(e) de l'entreprise <span class=\"v\">{{entreprise_nom}}</span>,</div>\n<p>a suivi l'action de formation suivante :</p>\n<div class=\"fiche\">\n  <div>Intitulé</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Nature de l'action</div><div>Action de formation (article L.6313-1 du Code du travail)</div>\n  <div>Dates</div><div>Du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Lieu</div><div>{{formation_lieu_nom}}</div>\n  <div>Durée prévue</div><div>{{formation_duree_heures_total}} heures</div>\n  <div>Durée effectivement réalisée</div><div class=\"v\">{{attestation_heures_realisees}} heures, attestées par l'émargement</div>\n  <div>Objectifs de la formation</div><div>{{formation_objectifs}}</div>\n  <div>Résultat de l'évaluation des acquis</div><div><span class=\"v\">{{evaluation_acquis_niveau_atteinte}}</span><!-- si:evaluation_acquis_score --> ({{evaluation_acquis_score}})<!-- /si:evaluation_acquis_score --></div>\n  <!-- si:formation_objectifs_atteints --><div>Objectifs atteints</div><div>{{formation_objectifs_atteints}}</div><!-- /si:formation_objectifs_atteints -->\n</div>\n<p style=\"margin-top:7mm\">Fait à <span class=\"v\">{{signature_lieu}}</span>, le <span class=\"v\">{{attestation_date}}</span>.</p>\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Pour l'organisme de formation</div>\n    <div class=\"nom\">{{of_representant_prenom}} {{of_representant_nom}}</div>\n    <!-- zone:signature_of -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire — remise de l'attestation</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "10-FIN.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Facture formateur — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Facture n° {{facture_formateur_numero}}</h1>\n<p class=\"sous-titre\">Prestation de sous-traitance de formation — dossier {{dossier_reference}}</p>\n<div class=\"parties\">\n  <div class=\"partie\">\n    <div class=\"role\">Émetteur — le sous-traitant</div>\n    <p><span class=\"v\">{{formateur_entreprise_nom}}</span><br>{{formateur_entreprise_adresse}}</p>\n    <p>SIRET : {{formateur_entreprise_siret}}<br>Déclaration d'activité n° {{formateur_nda_numero}} — DREETS {{formateur_dreets_region}}</p>\n    <p>{{formateur_prenom}} {{formateur_nom}} — {{formateur_email}}</p>\n  </div>\n  <div class=\"partie\">\n    <div class=\"role\">Destinataire — le donneur d'ordre</div>\n    <p><span class=\"v\">{{of_nom}}</span><br>{{of_adresse}}</p>\n    <p>SIRET : {{of_siret}}</p>\n    <p>{{of_email_comptabilite}}</p>\n  </div>\n</div>\n<div class=\"fiche\">\n  <div>Date de facture</div><div>{{facture_formateur_date}}</div>\n  <div>Échéance</div><div>{{facture_formateur_date_echeance}}</div>\n  <div>Formation</div><div>{{formation_titre}} — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Client final</div><div>{{entreprise_nom}}</div>\n</div>\n<table>\n  <thead><tr><th>Désignation</th><th class=\"num\">Heures</th><th class=\"num\">Coût horaire</th><th class=\"num\">Montant</th></tr></thead>\n  <tbody><tr><td>Animation de la formation « {{formation_titre}} »</td><td class=\"num\">{{formation_duree_heures_total}}</td><td class=\"num\">{{formateur_cout_horaire}}</td><td class=\"num\">{{formateur_montant_total}}</td></tr></tbody>\n</table>\n<div class=\"total\"><table>\n  <tr><td>Prix de vente HT de la formation</td><td class=\"num\">{{formation_prix_total_ht}}</td></tr>\n  <tr><td>Commission de portage ({{portage_commission_pourcentage}})</td><td class=\"num\">− {{portage_commission_montant}}</td></tr>\n  <tr><td>Net à payer</td><td class=\"num\">{{facture_formateur_net_a_payer}}</td></tr>\n</table></div>\n<p class=\"mention\">TVA non applicable — article 261.4.4° du CGI. Règlement sous 10 jours après le règlement du client ou du financeur, conformément à l'article 4 du contrat de sous-traitance.</p>\n<!-- si:formateur_iban --><div class=\"encadre\">Règlement par virement — IBAN : <span class=\"v\">{{formateur_iban}}</span><!-- si:formateur_bic --> — BIC : <span class=\"v\">{{formateur_bic}}</span><!-- /si:formateur_bic --></div><!-- /si:formateur_iban -->\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "11-FIN.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Facture — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Facture n° {{facture_of_numero}}</h1>\n<p class=\"sous-titre\">Action de formation professionnelle — dossier {{dossier_reference}}</p>\n<div class=\"parties\">\n  <div class=\"partie\">\n    <div class=\"role\">Émetteur</div>\n    <p><span class=\"v\">{{of_nom}}</span> — {{of_forme_juridique}}<br>{{of_adresse}}</p>\n    <p>SIRET : {{of_siret}}<!-- si:of_tva_intracom --><br>TVA intracommunautaire : {{of_tva_intracom}}<!-- /si:of_tva_intracom --></p>\n    <p>{{of_email_comptabilite}}<!-- si:of_telephone --> — {{of_telephone}}<!-- /si:of_telephone --></p>\n  </div>\n  <div class=\"partie\">\n    <div class=\"role\">Facturé à</div>\n    <p><span class=\"v\">{{entreprise_nom}}</span><br>{{entreprise_adresse}}</p>\n    <p>SIRET : {{entreprise_siret}}</p>\n    <!-- si:formation_opco --><p>Financeur : {{formation_opco}}<!-- si:facture_of_numero_adherent --> — n° d'adhérent {{facture_of_numero_adherent}}<!-- /si:facture_of_numero_adherent --></p><!-- /si:formation_opco -->\n  </div>\n</div>\n<div class=\"fiche\">\n  <div>Date de facture</div><div>{{facture_of_date}}</div>\n  <div>Échéance</div><div>{{facture_of_date_echeance}}</div>\n  <!-- si:facture_of_code_client --><div>Code client</div><div>{{facture_of_code_client}}</div><!-- /si:facture_of_code_client -->\n  <div>Stagiaire(s)</div><div>{{formation_liste_stagiaires}}</div>\n  <div>Période et lieu</div><div>Du {{formation_date_debut}} au {{formation_date_fin}} — {{formation_lieu_nom}}</div>\n</div>\n<table>\n  <thead><tr><th>Désignation</th><th class=\"num\">Heures</th><th class=\"num\">Prix unitaire HT</th><th class=\"num\">Stagiaires</th><th class=\"num\">Montant HT</th></tr></thead>\n  <tbody><tr><td>Formation « {{formation_titre}} »<!-- si:formation_duree_heures_distanciel --><br><span class=\"mention\">dont {{formation_duree_heures_distanciel}} heures à distance</span><!-- /si:formation_duree_heures_distanciel --></td><td class=\"num\">{{formation_duree_heures_total}}</td><td class=\"num\">{{facture_of_prix_unitaire_ht}}</td><td class=\"num\">{{formation_nb_stagiaires}}</td><td class=\"num\">{{facture_of_montant_ht}}</td></tr></tbody>\n</table>\n<div class=\"total\"><table>\n  <tr><td>Total HT</td><td class=\"num\">{{facture_of_montant_ht}}</td></tr>\n  <tr><td>TVA</td><td class=\"num\">{{facture_of_montant_tva}}</td></tr>\n  <tr><td>Total TTC</td><td class=\"num\">{{facture_of_montant_ttc}}</td></tr>\n  <!-- si:facture_of_acompte --><tr><td>Acompte versé</td><td class=\"num\">− {{facture_of_acompte}}</td></tr><!-- /si:facture_of_acompte -->\n  <tr><td>Solde dû</td><td class=\"num\">{{facture_of_solde_du}}</td></tr>\n</table></div>\n<p class=\"mention\">Exonération de TVA — article 261.4.4° du CGI. Déclaration d'activité n° {{of_nda_numero}} auprès de la DREETS {{of_dreets_region}}.<!-- si:of_certification_complementaire_numero --> Certification n° {{of_certification_complementaire_numero}}.<!-- /si:of_certification_complementaire_numero --></p>\n<div class=\"encadre\">Règlement par virement — {{of_banque_nom}} — IBAN : <span class=\"v\">{{of_iban}}</span> — BIC : <span class=\"v\">{{of_bic}}</span></div>\n<p class=\"mention\">En cas de retard de paiement, une pénalité égale à trois fois le taux d'intérêt légal est exigible, ainsi qu'une indemnité forfaitaire pour frais de recouvrement de 40 €. Tout litige relève du {{of_tribunal_competent}}.</p>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "12-APR.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Évaluation à froid — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Évaluation « à froid » de l'action de formation</h1>\n<p class=\"sous-titre\">Impact à moyen terme, trois mois après la formation — indicateur Qualiopi n° 30</p>\n<div class=\"fiche\">\n  <div>Stagiaire</div><div class=\"v\">{{stagiaire_1_nom}}</div>\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Durée</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<div class=\"fiche\"><div>Organisme de formation</div><div>{{of_nom}}</div><div>Formation terminée le</div><div>{{formation_date_fin}}</div><div>Évaluation renseignée le</div><div>{{satisfaction_froid_date}}</div></div>\n<!-- zone:grille_satisfaction_froid -->\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire ou l'entreprise</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "PRE.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Pré-dossier — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Pré-dossier de formation</h1>\n<p class=\"sous-titre\">Synthèse du recueil des besoins et du test de positionnement, soumise à la validation du stagiaire</p>\n<div class=\"fiche\">\n  <div>Stagiaire</div><div class=\"v\">{{stagiaire_1_nom}}</div>\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Durée</div><div>{{formation_duree_heures_total}} heures — du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<div class=\"fiche\">\n  <div>Entreprise</div><div>{{entreprise_nom}}</div>\n  <div>Objectifs de la formation</div><div>{{formation_objectifs}}</div>\n  <div>Niveau visé</div><div>{{formation_niveau}}</div>\n  <div>Modalité</div><div>{{formation_modalite}}</div>\n</div>\n<h2>1. Recueil des besoins</h2>\n<!-- zone:reponses_recueil -->\n<h2>2. Test de positionnement</h2>\n<!-- zone:synthese_positionnement -->\n<!-- si:positionnement_ajustement --><h3>Ajustement du programme retenu</h3><p>{{positionnement_ajustement}}</p><!-- /si:positionnement_ajustement -->\n<div class=\"encadre\">En validant ce pré-dossier, je confirme que les informations ci-dessus reflètent mes besoins et mon niveau de départ, et que le programme de la formation m'a été communiqué.</div>\n<div class=\"signatures\">\n  <div class=\"signature\">\n    <div class=\"qui\">Le stagiaire</div>\n    <div class=\"nom\">{{stagiaire_1_nom}}</div>\n    <!-- zone:signature_apprenant -->\n  </div>\n  <div class=\"signature\">\n    <div class=\"qui\">Le formateur</div>\n    <div class=\"nom\">{{formateur_prenom}} {{formateur_nom}}</div>\n    <!-- zone:signature_formateur -->\n  </div>\n</div>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "PRG.html": "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>Programme de formation — {{dossier_reference}}</title>\n<style><!-- inclure:styles --></style>\n</head>\n<body>\n<div class=\"page\">\n<!-- inclure:entete -->\n\n<h1>Programme de formation</h1>\n<p class=\"sous-titre\">Annexe à la convention n° {{dossier_reference}}</p>\n<div class=\"fiche\">\n  <div>Intitulé de la formation</div><div class=\"v\">{{formation_titre}}</div>\n  <div>Stagiaire(s)</div><div>{{formation_liste_stagiaires}}</div>\n  <div>Période</div><div>Du {{formation_date_debut}} au {{formation_date_fin}}</div>\n  <div>Durée totale</div><div>{{formation_duree_heures_total}} heures sur {{formation_duree_jours}} jour(s)</div>\n  <div>Modalité</div><div>{{formation_modalite}}</div>\n  <div>Formateur</div><div>{{formateur_prenom}} {{formateur_nom}}</div>\n</div>\n<div class=\"fiche\">\n  <!-- si:formation_public_vise --><div>Public visé</div><div>{{formation_public_vise}}</div><!-- /si:formation_public_vise -->\n  <div>Niveau</div><div>{{formation_niveau}}</div>\n  <div>Prérequis</div><div>{{formation_prerequis}}</div>\n</div>\n<h2>Objectifs pédagogiques</h2>\n<p>{{formation_objectifs}}</p>\n<h2>Contenu de la formation</h2>\n<p>{{formation_programme}}</p>\n<h2>Modalités d'évaluation</h2>\n<p>Recueil des besoins et test de positionnement avant la formation ; évaluation des acquis en fin de formation ; enquêtes de satisfaction à chaud et à froid. Une attestation de réalisation est remise à l'issue de l'action.</p>\n<p class=\"mention\">Programme transmis en annexe de la convention de formation. Toute modification fait l'objet d'un nouveau programme communiqué aux parties.</p>\n\n<!-- inclure:pied -->\n</div>\n</body>\n</html>\n",
  "fragments/entete.html": "<header class=\"entete\">\n  <div class=\"of\">\n    <!-- zone:logo_of -->\n    <strong>{{of_nom}}</strong>\n    {{of_adresse}}<br>\n    Déclaration d'activité n° {{of_nda_numero}} auprès de la DREETS {{of_dreets_region}}\n  </div>\n  <div class=\"reference\">Dossier<b>{{dossier_reference}}</b></div>\n</header>\n",
  "fragments/pied.html": "<footer class=\"pied\">\n  {{of_nom}} — {{of_forme_juridique}} — {{of_adresse}} — SIRET {{of_siret}}<br>\n  Déclaration d'activité enregistrée sous le n° {{of_nda_numero}} auprès de la DREETS {{of_dreets_region}}. Cet enregistrement ne vaut pas agrément de l'État.\n  <!-- si:of_qualiopi_numero --><br>Certification Qualiopi n° {{of_qualiopi_numero}} délivrée au titre de la catégorie « actions de formation ».<!-- /si:of_qualiopi_numero -->\n</footer>\n",
  "fragments/styles.css": "/* Feuille de style commune à toutes les pièces. Pensée pour l'impression A4 et la conversion PDF. */\n@page { size: A4; margin: 16mm 15mm 18mm; }\n@page paysage { size: A4 landscape; margin: 12mm; }\n* { box-sizing: border-box; }\nhtml { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\nbody { margin: 0; font-family: \"Inter\", \"Segoe UI\", Arial, sans-serif; font-size: 10.5pt; line-height: 1.5; color: #1f2a24; background: #fff; }\n.page { max-width: 180mm; margin: 0 auto; padding: 8mm 0; }\n.page.paysage { max-width: 270mm; page: paysage; }\nheader.entete { display: flex; justify-content: space-between; align-items: flex-start; gap: 12mm; padding-bottom: 5mm; margin-bottom: 7mm; border-bottom: 2px solid var(--of-couleur, #1d6a45); }\nheader.entete .of { font-size: 9pt; color: #5b6472; line-height: 1.45; }\nheader.entete .of strong { display: block; font-size: 13pt; letter-spacing: .02em; color: var(--of-couleur, #1d6a45); }\nheader.entete .reference { text-align: right; font-size: 9pt; color: #5b6472; white-space: nowrap; }\nheader.entete .reference b { display: block; font-size: 11pt; color: #1f2a24; font-variant-numeric: tabular-nums; }\nheader.entete img.logo { max-height: 16mm; max-width: 45mm; display: block; margin-bottom: 2mm; }\nh1 { font-size: 17pt; line-height: 1.2; margin: 0 0 2mm; color: #1f2a24; letter-spacing: -.01em; }\nh1 + .sous-titre { margin: 0 0 7mm; color: #5b6472; font-size: 10pt; }\nh2 { font-size: 11.5pt; margin: 7mm 0 2.5mm; color: var(--of-couleur, #1d6a45); break-after: avoid; }\nh3 { font-size: 10.5pt; margin: 4mm 0 1.5mm; break-after: avoid; }\np { margin: 0 0 2.5mm; }\nul { margin: 0 0 3mm; padding-left: 5mm; }\nli { margin-bottom: 1mm; }\n.v { font-weight: 600; }\n.parties { display: grid; grid-template-columns: 1fr 1fr; gap: 6mm; margin: 4mm 0 6mm; }\n.partie { border: 1px solid #d6ddd8; border-radius: 2mm; padding: 4mm; break-inside: avoid; }\n.partie .role { font-size: 8pt; text-transform: uppercase; letter-spacing: .08em; color: #5b6472; margin-bottom: 1.5mm; }\n.fiche { display: grid; grid-template-columns: 52mm 1fr; border: 1px solid #d6ddd8; border-radius: 2mm; margin: 3mm 0 5mm; overflow: hidden; }\n.fiche > div { padding: 2mm 3.5mm; border-bottom: 1px solid #e8ece9; }\n.fiche > div:nth-child(odd) { background: #f4f6f5; color: #5b6472; font-size: 9.5pt; }\n.fiche > div:nth-last-child(-n+2) { border-bottom: 0; }\ntable { width: 100%; border-collapse: collapse; margin: 3mm 0 5mm; font-size: 9.5pt; }\nth { text-align: left; font-weight: 600; background: #f4f6f5; color: #5b6472; font-size: 8.5pt; text-transform: uppercase; letter-spacing: .05em; }\nth, td { border: 1px solid #d6ddd8; padding: 2mm 2.5mm; vertical-align: top; }\ntd.num, th.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\ntr { break-inside: avoid; }\n.encadre { background: #f4f6f5; border-left: 3px solid var(--of-couleur, #1d6a45); padding: 3mm 4mm; margin: 4mm 0; border-radius: 0 2mm 2mm 0; break-inside: avoid; }\n.total { display: flex; justify-content: flex-end; }\n.total table { width: 80mm; }\n.total tr:last-child td { font-weight: 700; font-size: 11pt; background: #f4f6f5; }\n.signatures { display: grid; grid-template-columns: 1fr 1fr; gap: 8mm; margin-top: 8mm; break-inside: avoid; }\n.signature { border: 1px solid #d6ddd8; border-radius: 2mm; padding: 3mm 4mm; min-height: 38mm; }\n.signature .qui { font-size: 8.5pt; color: #5b6472; margin-bottom: 1mm; }\n.signature .nom { font-weight: 600; margin-bottom: 2mm; }\n.signature img { display: block; max-height: 22mm; max-width: 100%; }\n.signature .preuve { font-size: 7.5pt; color: #5b6472; line-height: 1.35; margin-top: 1.5mm; }\n.signature .attente { color: #9aa3a0; font-size: 8.5pt; font-style: italic; padding-top: 12mm; }\n.case-emargement img { max-height: 9mm; max-width: 32mm; display: block; }\n.case-emargement small { font-size: 6.5pt; color: #5b6472; }\n.mention { font-size: 8pt; color: #5b6472; }\nfooter.pied { margin-top: 9mm; padding-top: 3mm; border-top: 1px solid #d6ddd8; font-size: 7.5pt; color: #5b6472; text-align: center; line-height: 1.45; }\n.saut { break-before: page; }\n.qcm li { margin-bottom: 3mm; list-style: none; }\n.qcm ol { padding-left: 0; counter-reset: q; }\n.qcm ol > li { counter-increment: q; break-inside: avoid; }\n.qcm ol > li > .enonce::before { content: counter(q) \". \"; font-weight: 700; color: var(--of-couleur, #1d6a45); }\n.qcm .propositions { margin: 1.5mm 0 0 5mm; padding: 0; }\n.qcm .propositions li { margin-bottom: .8mm; list-style: none; }\n.qcm .coche { display: inline-block; width: 3.2mm; height: 3.2mm; border: 1px solid #5b6472; border-radius: .6mm; margin-right: 2mm; vertical-align: -0.4mm; }\n.qcm .coche.choisie { background: var(--of-couleur, #1d6a45); border-color: var(--of-couleur, #1d6a45); }\n.reponse { border: 1px solid #d6ddd8; border-radius: 2mm; padding: 2.5mm 3.5mm; min-height: 12mm; margin: 1mm 0 4mm; background: #fcfdfc; }\n/* À l'impression, un demi-millimètre de marge interne évite que le filet droit des tableaux soit rogné. */\n@media print { .page, .page.paysage { max-width: none; padding: 0 0.5mm; } }\n@media screen { body { background: #eef1ef; } .page { background: #fff; padding: 14mm 15mm; margin: 8mm auto; box-shadow: 0 1px 8px rgba(31,42,36,.12); max-width: 210mm; } .page.paysage { max-width: 297mm; } }\n"
};
